Test method 4:

```java
@Test
void testCheckDiscriminatorMatch_ExplicitMappingNoMatch_ImplicitFallback() {
    // Arrange
    DiscriminatorContext context = new DiscriminatorContext();
    ObjectNode discriminator = OBJECT_MAPPER.createObjectNode();
    ObjectNode mappingNode = OBJECT_MAPPER.createObjectNode();
    // mapping for a different value
    String otherSchemaLocation = "#/definitions/DogSchema";
    mappingNode.set("dog", OBJECT_MAPPER.textNode(otherSchemaLocation));
    discriminator.set("mapping", mappingNode);
    String discriminatorPropertyValue = "cat"; // does not match "dog"
    JsonSchema jsonSchema = mock(JsonSchema.class);
    // Mock getSchemaByReference for implicit match
    JsonSchema implicitSchema = mock(JsonSchema.class);
    when(jsonSchema.getSchemaByReference(discriminatorPropertyValue)).thenReturn(implicitSchema);
    // Mock getSchemaNode to return a node without the mapping key "dog"
    JsonNode schemaNode = mock(JsonNode.class);
    when(schemaNode.has("dog")).thenReturn(false);
    when(jsonSchema.getSchemaNode()).thenReturn(schemaNode);

    // Act
    BaseJsonValidator.checkDiscriminatorMatch(context, discriminator, discriminatorPropertyValue, jsonSchema);

    // Assert
    assertTrue(context.isDiscriminatorMatchFound(), "Discriminator match should be found via implicit fallback");
    assertSame(implicitSchema, context.getSchema(discriminatorPropertyValue), "Implicitly matched schema should be registered");
    // Ensure that the explicit mapping schema was not registered
    assertNull(context.getSchema(otherSchemaLocation), "Explicit mapping schema should not be registered when it does not match");
}
```

