private static void checkForExplicitDiscriminatorMappingMatch(final DiscriminatorContext currentDiscriminatorContext,
        final String discriminatorPropertyValue,
        final JsonNode discriminatorMapping,
        final JsonSchema schema) {
    if (discriminatorMapping.isObject()) {
        final Iterator<Map.Entry<String, JsonNode>> fields = discriminatorMapping.fields();
        while (fields.hasNext()) {
            final Map.Entry<String, JsonNode> entry = fields.next();
            final String key = entry.getKey();
            final JsonNode value = entry.getValue();
            if (key.equals(discriminatorPropertyValue)) {
                // value can be a string (schema location) or an object (inline schema)
                if (value.isTextual()) {
                    // schema location
                    final String schemaLocation = value.textValue();
                    final JsonSchema referencedSchema = schema.getSchemaByReference(schemaLocation);
                    if (referencedSchema != null) {
                        currentDiscriminatorContext.registerSchema(schemaLocation, referencedSchema);
                        currentDiscriminatorContext.markDiscriminatorMatchFound();
                    }
                } else if (value.isObject()) {
                    // inline schema
                    final JsonSchema inlineSchema = schema.getSchemaByReference(schemaLocation);
                    // The inline schema is not supported currently.
                    // TODO: support inline schema
                }
                // Once matched, break
                break;
            }
        }
    }
}
